      "passage": "「ほめる教育」が注目されて久しいが、何でも無条件に称賛すればよいというわけではない。子どもが自らの努力で達成したプロセスに目を向けず、単に結果や才能だけをほめ続けると、失敗を恐れて新しい挑戦を避けるようになるという研究結果もある。\n真の励ましとは、結果の巧拙ではなく、試行錯誤の過程そのものを温かく見守り認めることにある。",
